<?php declare(strict_types=1); ?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مدیریت محصولات 3D | کاردان چوب</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.rtl.min.css"><style>body{background:#f4f0ea;font-family:Tahoma,Arial}.top{background:#211a15;color:#fff;padding:22px}.card{border:0;box-shadow:0 8px 25px #39291a12}.sw{width:26px;height:26px;border-radius:50%;display:inline-block;border:1px solid #bbb}.model{background:#eee5d9;border-radius:8px;height:150px;display:grid;place-items:center;color:#80674f;font-weight:bold}</style></head><body><header class="top"><div class="container"><h3 class="mb-1">کاردان چوب · مدیریت محصولات 3D</h3><small>مدیریت محصول، مدل GLB/GLTF، متریال و ابعاد</small></div></header><main class="container py-4"><div class="row g-4"><div class="col-lg-7"><div class="card p-4"><div class="d-flex justify-content-between align-items-center mb-3"><h5>محصولات</h5><button class="btn btn-dark" onclick="loadProducts()">بروزرسانی</button></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>محصول</th><th>قیمت پایه</th><th>مدل 3D</th><th>وضعیت</th></tr></thead><tbody id="rows"><tr><td colspan="4">در حال بارگذاری…</td></tr></tbody></table></div></div></div><div class="col-lg-5"><div class="card p-4"><h5>محصول جدید</h5><form id="productForm" class="mt-3"><input class="form-control mb-2" name="name" placeholder="نام محصول" required><input class="form-control mb-2" name="slug" placeholder="slug انگلیسی" required><input class="form-control mb-2" name="base_price" type="number" min="0" placeholder="قیمت پایه" required><input class="form-control mb-2" name="model_3d_url" placeholder="/models/arya.glb"><input class="form-control mb-2" name="thumbnail_url" placeholder="/images/arya.webp"><textarea class="form-control mb-3" name="description" rows="3" placeholder="توضیحات"></textarea><button class="btn btn-dark w-100">ذخیره محصول</button></form><div id="message" class="mt-3"></div></div></div></div><div class="row g-4 mt-1"><div class="col-md-6"><div class="card p-4"><h5>متریال جدید</h5><form id="materialForm" class="mt-3"><select class="form-select mb-2" name="type"><option value="wood">چوب</option><option value="fabric">پارچه</option><option value="metal">فلز</option></select><input class="form-control mb-2" name="name" placeholder="نام متریال" required><input class="form-control mb-2" name="color_hex" placeholder="#5b3b25"><input class="form-control mb-3" name="price_delta" type="number" placeholder="تغییر قیمت"><button class="btn btn-outline-dark">افزودن متریال</button></form></div></div><div class="col-md-6"><div class="card p-4"><h5>استاندارد مدل 3D</h5><div class="model mt-3">GLB / GLTF + PBR + Draco</div><p class="text-muted small mt-3 mb-0">URL مدل در محصول ذخیره می‌شود. فایل تولیدی را در public/models قرار دهید و نام متریال‌ها را برای wood / fabric / metal استاندارد کنید.</p></div></div></div></main><script>async function api(url,opt){const r=await fetch(url,opt);return r.json()}async function loadProducts(){const r=await api('/api/admin/products.php');document.getElementById('rows').innerHTML=r.products.map(p=>`<tr><td><b>${p.name}</b><br><small>${p.slug}</small></td><td>${Number(p.base_price).toLocaleString('fa-IR')} تومان</td><td>${p.model_3d_url?'✓ GLB':'—'}</td><td>${p.is_active?'فعال':'غیرفعال'}</td></tr>`).join('')||'<tr><td colspan="4">محصولی وجود ندارد.</td></tr>'}document.getElementById('productForm').onsubmit=async e=>{e.preventDefault();const r=await api('/api/admin/products.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});document.getElementById('message').textContent=r.success?'محصول ذخیره شد.':r.message;if(r.success){e.target.reset();loadProducts()}};document.getElementById('materialForm').onsubmit=async e=>{e.preventDefault();const r=await api('/api/admin/materials.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});alert(r.success?'متریال ذخیره شد.':r.message);if(r.success)e.target.reset()};loadProducts();</script></body></html>
